use strict;
use warnings;
use File::Find;
use File::Basename;

my $root = "/bench/repo";
my $internal = "$root/internal";

# Collect declarations
my @decls; # {file, typ, name, line, test}

find(sub {
  return unless /\.go$/;
  my $path = $File::Find::name;
  my $test = /_test\.go$/ ? 1 : 0;
  open my $fh, "<", $path or die $!;
  my $n = 0;
  while (my $line = <$fh>) {
    $n++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      my $typ = undef;
      if (defined $recv) {
        my @p = split(/\s+/, $recv);
        $typ = $p[-1];
        $typ =~ s/^\*//;
      }
      push @decls, {file=>$path, typ=>$typ, name=>$name, line=>$n, test=>$test, recv=>$recv};
    }
  }
  close $fh;
}, $internal);

print "Total decls: ", scalar(@decls), "\n";
print "Non-test decls: ", scalar(grep { !$_->{test} } @decls), "\n";

# Collect all go files for call search (backend)
my @gofiles;
find(sub {
  return unless /\.go$/;
  my $p = $File::Find::name;
  return if $p =~ m{/proto/gen/};
  return if $p =~ m{/web/};
  push @gofiles, $p;
}, $root);

print "Go files to scan: ", scalar(@gofiles), "\n";

# For each unique name, count occurrences of Name( across repo, minus declarations
# Then refine for methods.

my %by_name;
for my $d (@decls) {
  next if $d->{test}; # count production declarations
  push @{$by_name{$d->{name}}}, $d;
}

# Count call-like occurrences for each name
sub count_calls {
  my ($name) = @_;
  my $pat = qr/\b\Q$name\E\s*\(/;
  my $count = 0;
  my @sites;
  for my $f (@gofiles) {
    open my $fh, "<", $f or next;
    my $n = 0;
    while (my $line = <$fh>) {
      $n++;
      next if $line =~ /^\s*\/\//;
      next if $line =~ /^func\s+/; # skip declarations
      # skip method declarations more carefully
      if ($line =~ /^func\s+/) { next; }
      while ($line =~ /$pat/g) {
        $count++;
        push @sites, "$f:$n" if @sites < 8;
      }
    }
    close $fh;
  }
  return ($count, \@sites);
}

my @ranked;
for my $name (keys %by_name) {
  my ($c, $sites) = count_calls($name);
  my $d = $by_name{$name}[0];
  push @ranked, {name=>$name, count=>$c, file=>$d->{file}, typ=>$d->{typ}, ndecls=>scalar(@{$by_name{$name}}), sites=>$sites};
}

@ranked = sort { $b->{count} <=> $a->{count} } @ranked;
print "\nTop 25 names by call-like occurrences (non-test decls):\n";
for my $i (0..24) {
  last unless $ranked[$i];
  my $r = $ranked[$i];
  my $sym = $r->{typ} ? "$r->{typ}.$r->{name}" : $r->{name};
  my $rel = $r->{file};
  $rel =~ s{^/bench/repo/}{};
  print sprintf("%3d  %-40s  decls=%d  %s\n", $r->{count}, $sym, $r->{ndecls}, $rel);
}
'

