perl -e '
use strict;
use warnings;

open my $ilist, "<", "/tmp/internal_go.txt" or die $!;
my @internal = <$ilist>; chomp @internal; close $ilist;
open my $blist, "<", "/tmp/backend_go.txt" or die $!;
my @gofiles = <$blist>; chomp @gofiles; close $blist;

# All backend decls (to detect name collisions)
my %external_decl; # name -> count outside internal
my %internal_decl; # name -> [decls]

for my $path (@gofiles) {
  my $in_int = $path =~ m{/internal/} ? 1 : 0;
  my $test = $path =~ /_test\.go$/ ? 1 : 0;
  open my $fh, "<", $path or next;
  my $n = 0;
  while (my $line = <$fh>) {
    $n++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      my $typ;
      if (defined $recv) {
        my @p = split(/\s+/, $recv);
        $typ = $p[-1]; $typ =~ s/^\*//;
      }
      if ($in_int && !$test) {
        push @{$internal_decl{$name}}, {file=>$path, typ=>$typ, line=>$n, recv=>$recv};
      } elsif (!$in_int) {
        $external_decl{$name}++;
      }
    }
  }
  close $fh;
}

# Common names that are too ambiguous
my %ambiguous = map { $_ => 1 } qw(
  New Len Next Error String Close Start Stop Reset Run Write Read
  Get Set Add Delete Update List Create Parse Format Validate
  Kind Dump Type Name Value Less Swap ServeHTTP
);

sub count_pattern {
  my ($pat, $exclude_files) = @_;
  my $count = 0;
  my @sites;
  for my $f (@gofiles) {
    open my $fh, "<", $f or next;
    my $n = 0;
    while (my $line = <$fh>) {
      $n++;
      next if $line =~ /^\s*\/\//;
      next if $line =~ /^func\s+/; # declaration
      if ($line =~ /$pat/) {
        # count occurrences on the line
        my $c = () = $line =~ /$pat/g;
        $count += $c;
        push @sites, sprintf("%s:%d", $f =~ s{^/bench/repo/}{}r, $n) if @sites < 8;
      }
    }
    close $fh;
  }
  return ($count, \@sites);
}

my @ranked;
for my $name (keys %internal_decl) {
  next if $ambiguous{$name};
  my $decls = $internal_decl{$name};
  my $ndecl = scalar @$decls;
  my $ext = $external_decl{$name} || 0;
  # Prefer unique names
  my $is_method = defined $decls->[0]{typ};
  my $pat = $is_method ? qr/\.\Q$name\E\s*\(/ : qr/(?<!\.)\b\Q$name\E\s*\(/;
  my ($c, $sites) = count_pattern($pat);
  push @ranked, {
    name=>$name, count=>$c, ndecl=>$ndecl, ext=>$ext, is_method=>$is_method,
    file=>$decls->[0]{file}, typ=>$decls->[0]{typ}, sites=>$sites,
  };
}

@ranked = sort { $b->{count} <=> $a->{count} } @ranked;
print "Top unique-ish internal symbols:\n";
my $shown = 0;
for my $r (@ranked) {
  next if $r->{ndecl} > 1 && $r->{name} !~ /Compile/; # skip overloaded unless interesting
  # skip if many external decls with same name (collision)
  next if $r->{ext} > 3;
  $shown++;
  last if $shown > 35;
