my @internal = <$ilist>; chomp @internal; close $ilist;
open my $blist, "<", "/tmp/backend_go.txt" or die $!;
my @gofiles = <$blist>; chomp @gofiles; close $blist;

my %ambiguous = map { $_ => 1 } qw(
  New Len Next Error String Close Start Stop Reset Run Write Read
  Get Set Add Delete Update List Create Parse Format Validate
  Kind Dump Type Name Value Less Swap ServeHTTP matches
);

# decls: only package-level funcs AND methods separately
my @func_decls; # package functions
my @method_decls;

for my $path (@internal) {
  next if $path =~ /_test\.go$/;
  open my $fh, "<", $path or next;
  my $n = 0;
  while (my $line = <$fh>) {
    $n++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      next if $ambiguous{$name};
      if (defined $recv) {
        my @p = split /\s+/, $recv; my $typ = $p[-1]; $typ =~ s/^\*//;
        push @method_decls, {name=>$name, typ=>$typ, file=>$path, line=>$n};
      } else {
        push @func_decls, {name=>$name, file=>$path, line=>$n};
      }
    }
  }
  close $fh;
}

my @filedata;
for my $f (@gofiles) {
  open my $fh, "<", $f or next;
  local $/; my $c = <$fh>; close $fh;
  push @filedata, [$f, $c];
}

sub rank {
  my ($items, $is_method) = @_;
  my @rows;
  my %seen_name;
  for my $d (@$items) {
    $seen_name{$d->{name}}++;
  }
  for my $d (@$items) {
    next if $seen_name{$d->{name}} > 1; # skip overloaded names
    my $name = $d->{name};
    my $pat = $is_method ? qr/\.\Q$name\E\s*\(/ : qr/\b\Q$name\E\s*\(/;
    my $total=0; my %files; my %funcs; my $cur="?";
    for my $fd (@filedata) {
      my ($f, $content) = @$fd;
      my $n=0;
      for my $line (split /\n/, $content) {
        $n++;
        if ($line =~ /^func\s+(?:\([^)]+\)\s+)?([A-Za-z_][A-Za-z0-9_]*)/) { $cur=$1; }
        next if $line =~ /^func\s+/;
        next if $line =~ /^\s*\/\//;
        my $c = () = $line =~ /$pat/g;
        next unless $c;
        $total += $c;
        $files{$f} += $c;
        $funcs{"$f:$cur"} += $c;
      }
    }
    my $sym = $is_method ? "$d->{typ}.$name" : $name;
    my $rel = $d->{file}; $rel =~ s{^/bench/repo/}{};
    push @rows, [$total, scalar(keys %funcs), scalar(keys %files), $sym, $rel];
  }
  return @rows;
}

my @all = (rank(\@func_decls, 0), rank(\@method_decls, 1));
@all = sort { $b->[0] <=> $a->[0] } @all;
print sprintf("%-4s %-4s %-4s %-42s %s\n", "tot", "fn", "fl", "symbol", "path");
for my $i (0..24) {
  my $r = $all[$i];
  print sprintf("%3d  %3d  %3d  %-42s %s\n", $r->[0], $r->[1], $r->[2], $r->[3], $r->[4]);
}
'

