perl -e '
use strict;
use warnings;

# Entity types (persistent domain models)
my @types = qw(
  Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation
  MemoShare Reaction User UserIdentity UserSetting
);

# Also check related proto store types? stick to store.* structs

# Collect all go files outside store/
open my $blist, "<", "/tmp/backend_go.txt" or die $!;
my @all = <$blist>; chomp @all; close $blist;

my @files;
for my $f (@all) {
  next if $f =~ m{/store/};      # data layer
  next if $f =~ m{/store\.go$};  # n/a
  push @files, $f;
}

# Also include files that might have been missed
# Map file -> package dir
sub pkg_of {
  my $f = shift;
  $f =~ s{/[^/]+\.go$}{};
  $f =~ s{^/bench/repo/}{};
  return $f;
}

print "Outside-layer files: ", scalar(@files), "\n";
my %pkgs;
for my $f (@files) { $pkgs{pkg_of($f)}++; }
print "Outside-layer packages:\n";
for my $p (sort keys %pkgs) { print "  $p\n"; }

print "\n";
for my $t (@types) {
  my %hit_pkg;
  my %hit_file;
  for my $f (@files) {
    open my $fh, "<", $f or next;
    local $/; my $c = <$fh>; close $fh;
    # match store.Type as a type/value, not prefix of another name
    if ($c =~ /\bstore\.$t\b/) {
      $hit_file{$f}++;
      $hit_pkg{pkg_of($f)}++;
    }
  }
  print sprintf("%-22s pkgs=%2d files=%2d  [%s]\n", $t, scalar(keys %hit_pkg), scalar(keys %hit_file),
    join(", ", sort keys %hit_pkg));
}
'

